# Terraform: S3 + RDS + IAM service account module

Environment separation via **per-environment tfvars + separate state keys** (no workspaces — workspaces share a backend key and encourage accidental cross-env blast radius; separate keys give hard isolation).

```
.
├── modules/
│   ├── s3-assets/          # bucket, versioning, SSE, PAB, optional CRR
│   ├── rds-postgres/       # instance, subnet group, SG, secret
│   └── iam-service-account/# IRSA role (prod) / IAM user (dev), least-priv policy
├── envs/
│   ├── dev.tfvars
│   ├── prod.tfvars
│   ├── dev.backend.hcl
│   └── prod.backend.hcl
├── versions.tf
├── providers.tf
├── variables.tf
├── main.tf
└── outputs.tf
```

---

## `versions.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = "~> 5.40"
      configuration_aliases = [aws.replica]
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }

  # Partial config — completed per env with -backend-config=envs/<env>.backend.hcl
  backend "s3" {}
}
```

## `envs/dev.backend.hcl`

```hcl
bucket         = "acme-tfstate-us-east-1"
key            = "webapp/dev/terraform.tfstate"
region         = "us-east-1"
dynamodb_table = "acme-tfstate-locks"
encrypt        = true
```

## `envs/prod.backend.hcl`

```hcl
bucket         = "acme-tfstate-us-east-1"
key            = "webapp/prod/terraform.tfstate"
region         = "us-east-1"
dynamodb_table = "acme-tfstate-locks"
encrypt        = true
```

> Distinct `key` per environment ⇒ `terraform apply` against prod can never plan a diff on dev state. Requirement 7 satisfied structurally, not by convention.

---

## `providers.tf`

```hcl
provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Environment = var.environment
      Project     = var.project
      ManagedBy   = "terraform"
    }
  }
}

# Always configured; only *used* when replication is enabled.
provider "aws" {
  alias  = "replica"
  region = var.replica_region

  default_tags {
    tags = {
      Environment = var.environment
      Project     = var.project
      ManagedBy   = "terraform"
      Role        = "replica"
    }
  }
}
```

---

## `variables.tf`

```hcl
variable "project" {
  type        = string
  description = "Project slug, used as a name prefix."
  default     = "webapp"
}

variable "environment" {
  type        = string
  description = "Deployment environment."
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be one of: dev, prod."
  }
}

variable "region" {
  type        = string
  description = "Primary AWS region."
}

variable "replica_region" {
  type        = string
  description = "Region for S3 cross-region replication."
  default     = "us-west-2"
}

# --- networking (assumed pre-existing; RDS is never internet-facing) ---
variable "vpc_id" {
  type        = string
  description = "VPC hosting the database."
}

variable "private_subnet_ids" {
  type        = list(string)
  description = "Private subnets for the RDS subnet group (>= 2 AZs)."
  validation {
    condition     = length(var.private_subnet_ids) >= 2
    error_message = "At least two private subnets are required."
  }
}

variable "db_client_security_group_ids" {
  type        = list(string)
  description = "Security groups permitted to reach Postgres on 5432."
  default     = []
}

# --- S3 ---
variable "bucket_kms_key_arn" {
  type        = string
  description = "CMK for bucket SSE. Null => SSE-S3 (AES-256)."
  default     = null
}

variable "enable_replication" {
  type        = bool
  description = "Enable cross-region replication of the assets bucket."
  default     = false
}

# --- RDS ---
variable "db_instance_class" {
  type        = string
  description = "RDS instance class."
}

variable "db_allocated_storage" {
  type        = number
  default     = 20
}

variable "db_multi_az" {
  type        = bool
  default     = false
}

variable "db_backup_retention_days" {
  type        = number
  default     = 7
  validation {
    condition     = var.db_backup_retention_days >= 7
    error_message = "Backup retention must be >= 7 days."
  }
}

variable "db_engine_version" {
  type    = string
  default = "16.3"
}

variable "db_name" {
  type    = string
  default = "appdb"
}

variable "db_username" {
  type    = string
  default = "appuser"
}

# --- IAM ---
variable "oidc_provider_arn" {
  type        = string
  description = "EKS OIDC provider ARN for IRSA. Required when use_oidc_trust = true."
  default     = null
}

variable "oidc_provider_url" {
  type        = string
  description = "EKS OIDC issuer URL without https:// scheme."
  default     = null
}

variable "service_account_namespace" {
  type    = string
  default = "default"
}

variable "service_account_name" {
  type    = string
  default = "webapp"
}

variable "use_oidc_trust" {
  type        = bool
  description = "true => IRSA role only. false => additionally create an IAM user with programmatic access (dev)."
  default     = true
}
```

---

## `main.tf`

```hcl
locals {
  name_prefix = "${var.project}-${var.environment}"
}

module "assets" {
  source = "./modules/s3-assets"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  name_prefix        = local.name_prefix
  kms_key_arn        = var.bucket_kms_key_arn
  enable_replication = var.enable_replication
  replica_region     = var.replica_region
}

module "database" {
  source = "./modules/rds-postgres"

  name_prefix               = local.name_prefix
  vpc_id                    = var.vpc_id
  subnet_ids                = var.private_subnet_ids
  client_security_group_ids = var.db_client_security_group_ids

  engine_version           = var.db_engine_version
  instance_class           = var.db_instance_class
  allocated_storage        = var.db_allocated_storage
  multi_az                 = var.db_multi_az
  backup_retention_days    = var.db_backup_retention_days
  db_name                  = var.db_name
  username                 = var.db_username
  # dev may use the AWS-managed key; prod gets a dedicated CMK inside the module
  create_dedicated_kms_key = var.environment == "prod"
}

module "service_account" {
  source = "./modules/iam-service-account"

  name_prefix = local.name_prefix
  environment = var.environment

  bucket_arn = module.assets.bucket_arn
  secret_arn = module.database.secret_arn
  kms_key_arns = compact([
    var.bucket_kms_key_arn,
    module.database.kms_key_arn,
  ])

  use_oidc_trust            = var.use_oidc_trust
  oidc_provider_arn         = var.oidc_provider_arn
  oidc_provider_url         = var.oidc_provider_url
  service_account_namespace = var.service_account_namespace
  service_account_name      = var.service_account_name
}
```

---

## `modules/s3-assets/main.tf`

```hcl
terraform {
  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = "~> 5.40"
      configuration_aliases = [aws.replica]
    }
  }
}

locals {
  sse_algorithm = var.kms_key_arn == null ? "AES256" : "aws:kms"
}

resource "aws_s3_bucket" "this" {
  bucket = "${var.name_prefix}-assets"
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_key_arn
    }
    bucket_key_enabled = var.kms_key_arn != null
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# Deny any non-TLS access.
data "aws_iam_policy_document" "tls_only" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket     = aws_s3_bucket.this.id
  policy     = data.aws_iam_policy_document.tls_only.json
  depends_on = [aws_s3_bucket_public_access_block.this]
}

# ---------------------------------------------------------------- replication

resource "aws_s3_bucket" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = "${var.name_prefix}-assets-${var.replica_region}"
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count                   = var.enable_replication ? 1 : 0
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "replication_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count              = var.enable_replication ? 1 : 0
  name               = "${var.name_prefix}-s3-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume.json
}

data "aws_iam_policy_document" "replication" {
  count = var.enable_replication ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }
}

resource "aws_iam_role_policy" "replication" {
  count  = var.enable_replication ? 1 : 0
  name   = "replication"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count      = var.enable_replication ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  role       = aws_iam_role.replication[0].arn
  depends_on = [aws_s3_bucket_versioning.this, aws_s3_bucket_versioning.replica]

  rule {
    id     = "replicate-all"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD_IA"
    }
  }
}
```

### `modules/s3-assets/variables.tf`

```hcl
variable "name_prefix"        { type = string }
variable "kms_key_arn"        { type = string, default = null }
variable "enable_replication" { type = bool,   default = false }
variable "replica_region"     { type = string, default = "us-west-2" }
```

### `modules/s3-assets/outputs.tf`

```hcl
output "bucket_id"          { value = aws_s3_bucket.this.id }
output "bucket_arn"         { value = aws_s3_bucket.this.arn }
output "bucket_domain_name" { value = aws_s3_bucket.this.bucket_regional_domain_name }
output "replica_bucket_arn" {
  value = try(aws_s3_bucket.replica[0].arn, null)
}
```

---

## `modules/rds-postgres/main.tf`

```hcl
data "aws_caller_identity" "current" {}

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# ------------------------------------------------------------------ KMS (prod)

resource "aws_kms_key" "db" {
  count                   = var.create_dedicated_kms_key ? 1 : 0
  description             = "${var.name_prefix} RDS storage encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "db" {
  count         = var.create_dedicated_kms_key ? 1 : 0
  name          = "alias/${var.name_prefix}-rds"
  target_key_id = aws_kms_key.db[0].key_id
}

# ------------------------------------------------------------------ networking

resource "aws_db_subnet_group" "this" {
  name       = "${var.name_prefix}-db"
  subnet_ids = var.subnet_ids
}

resource "aws_security_group" "db" {
  name        = "${var.name_prefix}-db"
  description = "Postgres access for ${var.name_prefix}"
  vpc_id      = var.vpc_id

  egress {
    description = "No outbound required"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["127.0.0.1/32"]
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "clients" {
  for_each = toset(var.client_security_group_ids)

  security_group_id            = aws_security_group.db.id
  referenced_security_group_id = each.value
  from_port                    = 5432
  to_port                      = 5432
  ip_protocol                  = "tcp"
  description                  = "Postgres from ${each.value}"
}

# ------------------------------------------------------------------- instance

resource "aws_db_instance" "this" {
  identifier     = "${var.name_prefix}-pg"
  engine         = "postgres"
  engine_version = var.engine_version
  instance_class = var.instance_class

  allocated_storage     = var.allocated_storage
  max_allocated_storage = var.allocated_storage * 4
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = var.create_dedicated_kms_key ? aws_kms_key.db[0].arn : null

  db_name  = var.db_name
  username = var.username
  password = random_password.master.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false
  multi_az               = var.multi_az

  backup_retention_period   = var.backup_retention_days
  backup_window             = "03:00-04:00"
  maintenance_window        = "Mon:04:30-Mon:05:30"
  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.name_prefix}-pg-final"

  auto_minor_version_upgrade      = true
  performance_insights_enabled    = var.multi_az
  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  apply_immediately = false

  lifecycle {
    ignore_changes = [password] # rotated out-of-band via Secrets Manager
  }
}

# --------------------------------------------------------------------- secret

resource "aws_secretsmanager_secret" "db" {
  name                    = "${var.name_prefix}/db/connection"
  description             = "Postgres connection string for ${var.name_prefix}"
  kms_key_id              = var.create_dedicated_kms_key ? aws_kms_key.db[0].arn : null
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    engine   = "postgres"
    host     = aws_db_instance.this.address
    port     = aws_db_instance.this.port
    dbname   = var.db_name
    username = var.username
    password = random_password.master.result
    url      = format(
      "postgresql://%s:%s@%s:%d/%s?sslmode=require",
      var.username,
      urlencode(random_password.master.result),
      aws_db_instance.this.address,
      aws_db_instance.this.port,
      var.db_name,
    )
  })
}
```

### `modules/rds-postgres/variables.tf`

```hcl
variable "name_prefix"               { type = string }
variable "vpc_id"                    { type = string }
variable "subnet_ids"                { type = list(string) }
variable "client_security_group_ids" { type = list(string), default = [] }
variable "engine_version"            { type = string, default = "16.3" }
variable "instance_class"            { type = string }
variable "allocated_storage"         { type = number, default = 20 }
variable "multi_az"                  { type = bool,   default = false }
variable "db_name"                   { type = string }
variable "username"                  { type = string }
variable "create_dedicated_kms_key"  { type = bool,   default = false }

variable "backup_retention_days" {
  type    = number
  default = 7
  validation {
    condition     = var.backup_retention_days >= 7
    error_message = "backup_retention_days must be >= 7."
  }
}
```

### `modules/rds-postgres/outputs.tf`

```hcl
output "endpoint"       { value = aws_db_instance.this.address }
output "port"           { value = aws_db_instance.this.port }
output "instance_arn"   { value = aws_db_instance.this.arn }
output "security_group_id" { value = aws_security_group.db.id }
output "secret_arn"     { value = aws_secretsmanager_secret.db.arn }
output "kms_key_arn"    { value = try(aws_kms_key.db[0].arn, null) }
```

> The password is generated by Terraform and written **only** to Secrets Manager. It is never committed. It *does* land in state — hence the encrypted, locked S3 backend above. Nothing sensitive is exported from the root module.

---

## `modules/iam-service-account/main.tf`

```hcl
data "aws_iam_policy_document" "assume_oidc" {
  count = var.use_oidc_trust ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:sub"
      values   = ["system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "assume_user" {
  count = var.use_oidc_trust ? 0 : 1

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = [aws_iam_user.this[0].arn]
    }
  }
}

resource "aws_iam_role" "this" {
  name                 = "${var.name_prefix}-app"
  description          = "Application service account role for ${var.name_prefix}"
  max_session_duration = 3600
  assume_role_policy = var.use_oidc_trust ? (
    data.aws_iam_policy_document.assume_oidc[0].json
  ) : data.aws_iam_policy_document.assume_user[0].json
}

# ------------------------------------------------------------ least-privilege

data "aws_iam_policy_document" "app" {
  statement {
    sid    = "ListOwnBucket"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = [var.bucket_arn]
  }

  statement {
    sid    = "ReadWriteObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
    ]
    resources = ["${var.bucket_arn}/*"]
  }

  statement {
    sid    = "ReadDbSecret"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]
    resources = [var.secret_arn]
  }

  dynamic "statement" {
    for_each = length(var.kms_key_arns) > 0 ? [1] : []
    content {
      sid    = "UseDataKeys"
      effect = "Allow"
      actions = [
        "kms:Decrypt",
        "kms:GenerateDataKey",
      ]
      resources = var.kms_key_arns
    }
  }
}

# Belt and braces: no wildcard actions or resources may ever reach prod.
resource "terraform_data" "no_wildcards_in_prod" {
  lifecycle {
    precondition {
      condition = var.environment != "prod" || alltrue([
        for s in jsondecode(data.aws_iam_policy_document.app.json).Statement :
        !contains(flatten([s.Action]), "*") &&
        !anytrue([for a in flatten([s.Action]) : endswith(a, ":*")]) &&
        !contains(flatten([s.Resource]), "*")
      ])
      error_message = "Wildcard IAM actions/resources are not permitted in prod."
    }
  }
}

resource "aws_iam_policy" "app" {
  name        = "${var.name_prefix}-app"
  description = "Least-privilege application access for ${var.name_prefix}"
  policy      = data.aws_iam_policy_document.app.json
}

resource "aws_iam_role_policy_attachment" "app" {
  role       = aws_iam_role.this.name
  policy_arn = aws_iam_policy.app.arn
}

# ------------------------------------------------- dev-only programmatic user

resource "aws_iam_user" "this" {
  count = var.use_oidc_trust ? 0 : 1
  name  = "${var.name_prefix}-app"
  path  = "/service/"
}

data "aws_iam_policy_document" "user_assume_only" {
  count = var.use_oidc_trust ? 0 : 1

  statement {
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.this.arn]
  }
}

# The user can do exactly one thing: assume the app role.
resource "aws_iam_user_policy" "assume_only" {
  count  = var.use_oidc_trust ? 0 : 1
  name   = "assume-app-role"
  user   = aws_iam_user.this[0].name
  policy = data.aws_iam_policy_document.user_assume_only[0].json
}

resource "aws_iam_access_key" "this" {
  count = var.use_oidc_trust ? 0 : 1
  user  = aws_iam_user.this[0].name
}

resource "aws_secretsmanager_secret" "user_credentials" {
  count                   = var.use_oidc_trust ? 0 : 1
  name                    = "${var.name_prefix}/iam/access-key"
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "user_credentials" {
